Future<String> _today() async {
  try {
    final r = await http.get(Uri.parse('$kServer/time')).timeout(const Duration(seconds: 5));
    if (r.statusCode == 200) {
      return (jsonDecode(r.body)['date'] ?? '').toString();
    }
  } catch (_) {}
  return '';
}

/// 只认开发板上报的真数据（source=="board"）；模拟器(sim)记录一律忽略。
/// 没有 board 记录 → null → UI 显示 "--"（用户定案：没检测到就不显示假值）。
Future<Map<String, dynamic>?> latestSensor() async {
  try {
    final r = await http.get(Uri.parse('$kServer/data/sensor?limit=50'))
        .timeout(const Duration(seconds: 5));
    if (r.statusCode != 200) return null;
    final items = jsonDecode(r.body)['items'] as List? ?? [];
    for (final it in items) {
      if (it is Map<String, dynamic> && it['source'] == 'board') {
        return it;
      }
    }
    return null; // 只有 sim/旧数据 → 视为无
  } catch (_) {
    return null;
  }
}

