/****************************************************************************
 * cmd_opus — 极讯 codec 演示（V1）：板端 Opus 编解码能力自测
 *
 * P1 验收用途：
 *   1) 证明 libopus 在 ESP32-S3 上能跑（编/解全通）；
 *   2) 实测 CPU（每 20ms 帧的编码/解码耗时）与包大小（→ 实际码率）；
 *   3) 给出重建质量指标（对齐相关度/电平），确认"真人音色"路线可行。
 *
 * 用合成"类语音"信号（基频滑音 + 谐波 + 包络），不依赖麦克风。
 ****************************************************************************/

#define OPUS_TEST_RATE     16000
#define OPUS_TEST_FRAME    320      /* 20ms @16k */
#define OPUS_TEST_FRAMES   100      /* 2 秒 */
#define OPUS_TEST_BITRATE  16000    /* 16 kbps（V1 目标档位） */

static int cmd_opus(int argc, char *argv[])
{
  OpusEncoder *enc = NULL;
  OpusDecoder *dec = NULL;
  int err = OPUS_OK;
  static int16_t pcm_in[OPUS_TEST_FRAME];
  static int16_t pcm_out[OPUS_TEST_FRAME * 2];
  static uint8_t packet[512];
  struct timespec t0;
  struct timespec t1;
  double enc_ms = 0.0;
  double dec_ms = 0.0;
  int total_bytes = 0;
  int i;
  int f;
  int decoded_last = 0;
  double num = 0.0;
  double den_a = 0.0;
  double den_b = 0.0;
  int in_rms = 0;
  int out_rms = 0;

  if (argc >= 3 && strcmp(argv[2], "version") == 0)
    {
      printf("[OPUS] libopus version: %s\\n", opus_get_version_string());
      printf("[OPUS] 编码器状态 %d B / 解码器状态 %d B\\n",
             (int)opus_encoder_get_size(1), (int)opus_decoder_get_size(1));
      return 0;
    }

  enc = opus_encoder_create(OPUS_TEST_RATE, 1, OPUS_APPLICATION_VOIP, &err);
  if (enc == NULL || err != OPUS_OK)
    {
      printf("[OPUS] encoder create failed: %d\\n", err);
      return -1;
    }

  opus_encoder_ctl(enc, OPUS_SET_BITRATE(OPUS_TEST_BITRATE));
  opus_encoder_ctl(enc, OPUS_SET_INBAND_FEC(1));       /* 抗丢包（演示用） */
  opus_encoder_ctl(enc, OPUS_SET_DTX(0));              /* 演示：不做静音压缩 */

  dec = opus_decoder_create(OPUS_TEST_RATE, 1, &err);
  if (dec == NULL || err != OPUS_OK)
    {
      printf("[OPUS] decoder create failed: %d\\n", err);
      opus_encoder_destroy(enc);
      return -1;
    }

  printf("[OPUS] %s | 16kHz mono | 20ms/帧 | 目标 %d bps | %d 帧(%.1fs)\\n",
         opus_get_version_string(), OPUS_TEST_BITRATE,
         OPUS_TEST_FRAMES, OPUS_TEST_FRAMES * 0.02);

  for (f = 0; f < OPUS_TEST_FRAMES; f++)
    {
      int nbytes;
      int n;

      /* 合成类语音：基频 120→220Hz 滑音 + 5 次谐波 + 音节包络 */

      for (i = 0; i < OPUS_TEST_FRAME; i++)
        {
          double t = (f * OPUS_TEST_FRAME + i) / (double)OPUS_TEST_RATE;
          double f0 = 120.0 + 100.0 * (f / (double)OPUS_TEST_FRAMES);
          double v = 0.0;
          int h;

          for (h = 1; h <= 5; h++)
            {
              v += sin(2.0 * 3.14159265358979 * f0 * h * t) / h;
            }

          /* 每 25 帧一个"音节"包络（模拟说话断续） */
          v *= 0.5 * (1.0 - cos(2.0 * 3.14159265358979 *
                                ((f % 25) / 25.0)));
          pcm_in[i] = (int16_t)(v * 6000.0);
        }

      clock_gettime(CLOCK_MONOTONIC, &t0);
      nbytes = opus_encode(enc, pcm_in, OPUS_TEST_FRAME, packet, sizeof(packet));
      clock_gettime(CLOCK_MONOTONIC, &t1);

      if (nbytes < 0)
        {
          printf("[OPUS] encode failed: %d\\n", nbytes);
          break;
        }

      enc_ms += (t1.tv_sec - t0.tv_sec) * 1000.0 +
                (t1.tv_nsec - t0.tv_nsec) / 1e6;
      total_bytes += nbytes;

      clock_gettime(CLOCK_MONOTONIC, &t0);
      n = opus_decode(dec, packet, nbytes, pcm_out, OPUS_TEST_FRAME, 0);
      clock_gettime(CLOCK_MONOTONIC, &t1);

      if (n < 0)
        {
          printf("[OPUS] decode failed: %d\\n", n);
          break;
        }

      dec_ms += (t1.tv_sec - t0.tv_sec) * 1000.0 +
                (t1.tv_nsec - t0.tv_nsec) / 1e6;

      /* 累积相关度（解码有固定延迟，取后者对齐输入后半段） */

      {
        int off = n - OPUS_TEST_FRAME;

        for (i = 0; i < OPUS_TEST_FRAME; i++)
          {
            double a = pcm_in[i];
            double b = pcm_out[i + (off > 0 ? off : 0)];

            num += a * b;
            den_a += a * a;
            den_b += b * b;
          }
