{"content": "/****************************************************************************
 * apps/plant-companion/components/voice_call/voice_call.h
 *
 * 极讯 codec 演示（V1）· 板端通话组件
 *
 *   上行：麦克风 24k(MIC1) → 16k → PCM 帧 → UDP → 服务器（Opus 编码成 index）
 *   下行：UDP 收 index → 板端 libopus 解码 → 16k→24k 插值 → I2S 播放
 *   全双工；播放期间麦克风衰减（回声门控）+ 滞回，避免回声/啸叫。
 ****************************************************************************/

#ifndef __PLANT_COMPONENTS_VOICE_CALL_H
#define __PLANT_COMPONENTS_VOICE_CALL_H

#include <stdint.h>
#include <stdbool.h>

/* 通话统计（供 NSH `plant call stat` / 演示面板） */

struct voice_call_stats_s
{
  uint32_t tx_packets;      /* 上行已发 UDP 包 */
  uint32_t tx_frames;       /* 上行已发 PCM 帧（20ms/帧） */
  uint32_t rx_packets;      /* 下行已收 UDP 包 */
  uint32_t rx_frames;       /* 下行已解码 Opus 帧 */
  uint32_t rx_lost;         /* 按 seq 检测到的下行丢包 */
  uint32_t rx_bytes;        /* 下行 index 字节数（算码率用） */
  int      last_latency_ms; /* 最近一包的单向延迟（用包头 ts_ms 推算） */
  int      encoder_state;   /* 板端解码器状态字节数（内存占用参考） */
  bool     echo_gate_on;    /* 当前是否处于播放期麦克风衰减 */
};

/**
 * 启动通话
 * @param server_host 服务器 IP（如 "192.168.3.148"）
 * @param port        中转端口（call_relay.py，默认 9500）
 * @param room        房间名（同房间的两块板互配）
 * @return 0 成功；负 errno
 */
int voice_call_start(const char *server_host, uint16_t port, const char *room);

/** 停止通话（发 BYE、关 socket、停线程） */
void voice_call_stop(void);

/** 是否在通话中 */
bool voice_call_running(void);

/** 取统计快照 */
void voice_call_get_stats(struct voice_call_stats_s *out);

/** 打印统计（NSH 用） */
void voice_call_print_stats(void);

#endif /* __PLANT_COMPONENTS_VOICE_CALL_H */
