{"content": "/****************************************************************************
 * apps/plant-companion/components/voice_call/voice_call.c
 *
 * 极讯 codec 演示（V1）· 板端通话实现
 *
 * 链路（与 tools/server/call_relay.py 协议一致）：
 *   上行 UDP 包：14B 包头 + N×640B（16kHz mono PCM16，20ms/帧）
 *   下行 UDP 包：14B 包头 + N×(2B 长度前缀 + Opus 包)
 *
 * 板端职责（V1 定案）：只做采集上行 + 解码下行；编码在服务器。
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include <opus.h>

#include "voice_call.h"
#include "../../hal/hal_i2s.h"
#include "../../ai_module/ai_voice/ai_voice.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VC_MAGIC            0xC1
#define VC_T_AUDIO          0
#define VC_T_HELLO          1
#define VC_T_BYE            2
#define VC_T_STATS          3

#define VC_RATE             16000    /* 下行/上行 PCM 采样率 */
#define VC_I2S_RATE         24000    /* I2S 实际速率（ES8311/ES7210） */
#define VC_FRAME            320      /* 20ms @16k */
#define VC_MIC24_FRAME      (VC_I2S_RATE / 50)   /* 20ms @24k = 480 */

#define VC_PREBUFFER        3        /* 起播前先攒 3 帧（60ms）抗抖动 */
#define VC_ECHO_GATE_GAIN   0.12f    /* 播放期麦克风衰减 ≈ -18dB */
#define VC_ECHO_HANGOVER_MS 120      /* 停播后继续衰减的滞回 */

#define VC_HDR_LEN          14
#define VC_MAX_PKT          1400

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct vc_hdr_s
{
  uint8_t  magic;
  uint8_t  type;
  uint16_t sid;
  uint32_t seq;
  uint32_t ts_ms;
  uint16_t frames;
} __attribute__((packed));

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int      g_sock = -1;
static struct sockaddr_in g_srv;
static bool     g_run;
static pthread_t g_tx_tid;
static pthread_t g_rx_tid;
static OpusDecoder *g_dec;
static struct voice_call_stats_s g_st;
static volatile uint32_t g_last_play_ms;   /* 最近一次播放时刻（回声门控用） */
static char     g_room[32];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t vc_now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static uint32_t vc_ms32(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  return (uint32_t)((uint64_t)ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static int vc_ms32_diff(uint32_t newer, uint32_t older)
{
  uint32_t d = (newer - older) & 0xFFFFFFFFu;
  return (d < 0x80000000u) ? (int)d : -(int)(0xFFFFFFFFu - d);
}

static int vc_send(uint8_t type, uint32_t seq, uint16_t frames,
                   const void *payload, size_t plen)
{
  uint8_t buf[VC_MAX_PKT];
  struct vc_hdr_s *h = (struct vc_hdr_s *)buf;

  if (plen + VC_HDR_LEN > sizeof(buf))
    {
      return -EMSGSIZE;
    }

  h->magic = VC_MAGIC;
  h->type = type;
  h->sid = 0;
  h->seq = seq;
  h->ts_ms = vc_ms32();
  h->frames = frames;
  if (plen > 0)
    {
      memcpy(buf + VC_HDR_LEN, payload, plen);
    }

  return sendto(g_sock, buf, VC_HDR_LEN + plen, 0,
                (struct sockaddr *)&g_srv, sizeof(g_srv));
}

/* 播放期麦克风衰减（回声门控 + 滞回） */

static bool vc_echo_gate_active(void)
{
  uint32_t now = vc_now_ms();
  return (now - g_last_play_ms) < VC_ECHO_HANGOVER_MS;
}

/* 16k mono → 24k stereo（3:2 线性插值 + L/R 复制），与 ai_voice 播放同口径 */

static int vc_play_pcm16k(const int16_t *pcm, int samples)
{
  static int16_t out[VC_FRAME * 3 / 2 * 2];
  int n_out = 0;
  int j;

  for (j = 0; j < samples * 3 / 2; j++)
    {
      uint32_t pos = (uint32_t)j * 2;
      uint32_t i = pos / 3;
      uint32_t frac = pos % 3;
      int16_t a = pcm[i];
      int16_t b = ((int)(i + 1) < samples) ? pcm[i + 1] : a;
      int16_t s = (frac == 0) ? a
                : (int16_t)(((int32_t)a * (3 - (int32_t)frac) +
                             (int32_t)b * (int32_t)frac) / 3);

      out[n_out++] = s;   /* L */
      out[n_out++] = s;   /* R */
    }

  g_last_play_ms = vc_now_ms();
  return hal_i2s_write_async(out, (uint32_t)n_out * 2);
}

/****************************************************************************
 * TX 线程：麦克风 → 16k PCM → UDP（20ms/帧）
 ****************************************************************************/

static void *vc_tx_thread(void *arg)
{
  static int16_t mic24[VC_MIC24_FRAME];
  static int16_t pcm16[VC_FRAME];
  uint32_t seq = 0;

  (void)arg;

  while (g_run)
    {
      int n = hal_i2s_read_slot(mic24, sizeof(mic24), 0);   /* 20ms，阻塞 */
      int n16;
      int i;

      if (n <= 0)
        {
          usleep(2000);
          continue;
        }

      n16 = (int)ai_voice_decimate(pcm16, mic24, (uint32_t)(n / 2));
      if (n16 <= 0)
        {
          continue;
        }

      /* 回声门控：本机正在放远端声音时压低麦克风（+滞回） */

      g_st.echo_gate_on = vc_echo_gate_active();
      if (g_st.echo_gate_on)
        {
          for (i = 0; i < n16; i++)
            {
              pcm16[i] = (int16_t)(pcm16[i] * VC_ECHO_GATE_GAIN);
            }
        }

      if (vc_send(VC_T_AUDIO, seq++, 1, pcm16, (size_t)n16 * 2) > 0)
        {
          g_st.tx_packets++;
          g_st.tx_frames++;
        }
    }

  return NULL;
}

/****************************************************************************
 * RX 线程：收 index → Opus 解码 → I2S 播放（带预缓冲抗抖动）
 ****************************************************************************/

static void *vc_rx_thread(void *arg)
{
  static uint8_t buf[VC_MAX_PKT];
  static int16_t pcm[VC_FRAME * 4];
  int prebuf = 0;
  uint32_t last_seq = 0;
  bool have_seq = false;

  (void)arg;

  while (g_run)
    {
      ssize_t n;
      struct vc_hdr_s *h;
      uint8_t *payload;
      int plen;
      int off = 0;
      int latency;

      n = recv(g_sock, buf, sizeof(buf), 0);
      if (n < VC_HDR_LEN)
        {
          if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK ||
                        errno == EINTR))
            {
              continue;
            }

          if (n <= 0)
            {
              usleep(2000);
              continue;
            }

          continue;
        }

      h = (struct vc_hdr_s *)buf;
      if (h->magic != VC_MAGIC || h->type != VC_T_AUDIO)
        {
          continue;
        }

      payload = buf + VC_HDR_LEN;
      plen = (int)n - VC_HDR_LEN;
      g_st.rx_packets++;
      g_st.rx_bytes += (uint32_t)plen;

      latency = vc_ms32_diff(vc_ms32(), h->ts_ms);
      if (latency >= 0 && latency < 5000)
        {
          g_st.last_latency_ms = latency;
        }

      /* 丢包检测（seq 间隙 → 用 PLC 补帧，避免爆音） */

      if (have_seq)
        {
          uint32_t gap = (h->seq - last_seq) & 0xFFFFFFFFu;

          if (gap > 1 && gap < 100)
            {
              int k;

              g_st.rx_lost += gap - 1;
              for (k = 0; k < (int)(gap - 1) && k < 3; k++)
                {
                  int m = opus_decode(g_dec, NULL, 0, pcm, VC_FRAME, 0);

                  if (m > 0)
                    {
                      vc_play_pcm16k(pcm, m);
                    }
                }
            }
        }

      last_seq = h->seq;
      have_seq = true;

      /* 预缓冲：攒够 VC_PREBUFFER 帧再开播，吸收 WiFi 抖动 */

      if (prebuf < VC_PREBUFFER)
        {
          prebuf++;
          if (prebuf < VC_PREBUFFER)
            {
              continue;
            }
        }

      /* 切包（2B 长度前缀）→ 逐包解码播放 */

      while (off + 2 <= plen)
        {
          int ln = payload[off] | (payload[off + 1] << 8);
          int m;

          off += 2;
          if (ln <= 0 || off + ln > plen)
            {
              break;
            }

          m = opus_decode(g_dec, payload + off, ln, pcm, VC_FRAME * 4, 0);
          off += ln;

          if (m > 0)
            {
              g_st.rx_frames++;
              vc_play_pcm16k(pcm, m);
            }
          else if (m < 0)
            {
              printf("[CALL] opus_decode 失败: %d\n", m);
            }
        }
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int voice_call_start(const char *server_host, uint16_t port, const char *room)
{
  struct sockaddr_in local;
  struct timeval tv;
  pthread_attr_t attr;
  int err = OPUS_OK;
  int ret;

  if (g_run)
    {
      printf("[CALL] 已在通话中（先 plant call stop）\n");
      return -EBUSY;
    }

  if (server_host == NULL || room == NULL)
    {
      return -EINVAL;
    }

  memset(&g_st, 0, sizeof(g_st));
  memset(&g_srv, 0, sizeof(g_srv));
  g_srv.sin_family = AF_INET;
  g_srv.sin_port = htons(port);
  g_srv.sin_addr.s_addr = inet_addr(server_host);
  if (g_srv.sin_addr.s_addr == INADDR_NONE)
    {
      printf("[CALL] 服务器地址非法: %s\n", server_host);
      return -EINVAL;
    }

  g_sock = socket(AF_INET, SOCK_DGRAM, 0);
  if (g_sock < 0)
    {
      printf("[CALL] socket 失败: %d\n", errno);
      return -errno;
    }

  memset(&local, 0, sizeof(local));
  local.sin_family = AF_INET;
  local.sin_addr.s_addr = htonl(INADDR_ANY);
  local.sin_port = 0;
  if (bind(g_sock, (struct sockaddr *)&local, sizeof(local)) < 0)
    {
      printf("[CALL] bind 失败: %d\n", errno);
      close(g_sock);
      g_sock = -1;
      return -errno;
    }

  /* 收包超时 200ms：让 RX 线程能周期性检查退出标志 */

  tv.tv_sec = 0;
  tv.tv_usec = 200 * 1000;
  setsockopt(g_sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  g_dec = opus_decoder_create(VC_RATE, 1, &err);
  if (g_dec == NULL || err != OPUS_OK)
    {
      printf("[CALL] opus_decoder_create 失败: %d\n", err);
      close(g_sock);
      g_sock = -1;
      return -EIO;
    }

  g_st.encoder_state = opus_decoder_get_size(1);
  strncpy(g_room, room, sizeof(g_room) - 1);
  g_room[sizeof(g_room) - 1] = '\0';

  g_run = true;

  ret = vc_send(VC_T_HELLO, 0, 0, g_room, strlen(g_room));
  if (ret < 0)
    {
      printf("[CALL] HELLO 发送失败: %d\n", errno);
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  pthread_create(&g_tx_tid, &attr, vc_tx_thread, NULL);
  pthread_create(&g_rx_tid, &attr, vc_rx_thread, NULL);
  pthread_attr_destroy(&attr);

  printf("[CALL] 通话已启动: server=%s:%u room=%s 解码器状态=%d B\n",
         server_host, (unsigned)port, g_room, g_st.encoder_state);
  printf("[CALL] 上行 16k PCM(20ms/帧) → 服务器 Opus 编码 → 对端；"
         "下行 index → 板端 libopus 解码 → I2S 播放\n");
  return 0;
}

void voice_call_stop(void)
{
  if (!g_run)
    {
      return;
    }

  g_run = false;

  vc_send(VC_T_BYE, 0, 0, NULL, 0);

  pthread_join(g_tx_tid, NULL);
  pthread_join(g_rx_tid, NULL);

  hal_i2s_write_flush();

  if (g_dec != NULL)
    {
      opus_decoder_destroy(g_dec);
      g_dec = NULL;
    }

  if (g_sock >= 0)
    {
      close(g_sock);
      g_sock = -1;
    }

  printf("[CALL] 通话已结束（tx=%u 包 / rx=%u 包 / 丢 %u）\n",
         g_st.tx_packets, g_st.rx_packets, g_st.rx_lost);
}

bool voice_call_running(void)
{
  return g_run;
}

void voice_call_get_stats(struct voice_call_stats_s *out)
{
  if (out != NULL)
    {
      *out = g_st;
      out->echo_gate_on = vc_echo_gate_active();
    }
}

void voice_call_print_stats(void)
{
  struct voice_call_stats_s s;
  double secs = (double)(s.tx_frames * 20) / 1000.0;

  voice_call_get_stats(&s);

  printf("[CALL] ==== 通话统计 ====\n");
  printf("[CALL] 上行: %u 包 / %u 帧 (%.1fs) = %.1f kbps PCM\n",
         s.tx_packets, s.tx_frames, secs,
         secs > 0 ? (double)s.tx_frames * VC_FRAME * 2 * 8 / secs / 1000.0 : 0.0);
  printf("[CALL] 下行: %u 包 / %u 帧 / 丢 %u / index %u B = %.1f kbps\n",
         s.rx_packets, s.rx_frames, s.rx_lost, s.rx_bytes,
         secs > 0 ? (double)s.rx_bytes * 8 / secs / 1000.0 : 0.0);
  printf("[CALL] 单向延迟(最近): %d ms | 回声门控: %s | 解码器状态 %d B\n",
         s.last_latency_ms, s.echo_gate_on ? "ON(麦克风衰减中)" : "off",
         s.encoder_state);
  printf("[CALL] ==================\n");
}
