{"content": "/****************************************************************************
 * apps/plant-companion/components/voice_call/voice_call.c
 *
 * 极讯 codec 演示（V1 + 半双工，2026-09-10 定案）
 *
 * 链路（与 tools/server/call_relay.py 协议一致）：
 *   上行 UDP 包：14B 包头 + N×640B（16kHz mono PCM16，20ms/帧）
 *   下行 UDP 包：14B 包头 + N×(2B 长度前缀 + Opus 包)
 *
 * 为什么先做半双工（硬件约束，见 docs/CODEC_DEMO_REQUIREMENTS.md §3.5）：
 *   OpenVela 的 esp32s3_i2s 驱动当前 **不支持 TX/RX 并发**（单条 GDMA 通道，
 *   且 TX/RX ISR 挂在同一个 I2S0 中断上互相覆盖），hal_i2s 因此强制串行：
 *   要采集必须先 hal_i2s_write_flush() 等 TX 排空。
 *
 * 状态机（永不"边放边采"，靠能量自动切换，类似自动对讲机）：
 *
 *   LISTEN（放远端）──远端静音≥300ms──▶ PROBE（试听本地，采集不上行）
 *      ▲                                      │本地话音连续 2 帧
 *      │远端出现话音                            ▼
 *      └──────────────────────────────── TALK（采集+上行，不放音）
 *                        本地静音≥500ms → LISTEN
 *
 *   切换要点：进 PROBE/TALK 前 flush TX（等排空）；回 LISTEN 前等采集线程
 *   退出（g_capture_active 归零，≤60ms），避免驱动报 -EIO。
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include <opus.h>

#include "voice_call.h"
#include "../../hal/hal_i2s.h"
#include "../../ai_module/ai_voice/ai_voice.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VC_MAGIC            0xC1
#define VC_T_AUDIO          0
#define VC_T_HELLO          1
#define VC_T_BYE            2
#define VC_T_STATS          3

#define VC_RATE             16000
#define VC_I2S_RATE         24000
#define VC_FRAME            320                     /* 20ms @16k */
#define VC_MIC24_FRAME      (VC_I2S_RATE / 50)      /* 20ms @24k = 480 */

#define VC_HDR_LEN          14
#define VC_MAX_PKT          1400

/* 半双工切换参数 */

#define VC_ENERGY_TH        260        /* 帧 RMS 门限（≈ -42 dBFS，按环境可调） */
#define VC_TALK_FRAMES      2          /* 连续 2 帧(40ms)本地有话音 → 抢麦 */
#define VC_REMOTE_SIL_MS    300        /* 远端静音 ≥300ms → 允许本地试听 */
#define VC_LOCAL_SIL_MS     500        /* 本地静音 ≥500ms → 让回远端 */
#define VC_SWITCH_WAIT_MS   60         /* 回 LISTEN 前等采集线程退出 */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct vc_hdr_s
{
  uint8_t  magic;
  uint8_t  type;
  uint16_t sid;
  uint32_t seq;
  uint32_t ts_ms;
  uint16_t frames;
} __attribute__((packed));

enum vc_mode_e
{
  VC_MODE_LISTEN = 0,   /* 放远端，不采集 */
  VC_MODE_PROBE,        /* 远端静音，试听本地（采集但不上行） */
  VC_MODE_TALK          /* 本地说话：采集 + 上行，不放音 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int      g_sock = -1;
static struct sockaddr_in g_srv;
static bool     g_run;
static pthread_t g_tx_tid;
static pthread_t g_rx_tid;
static OpusDecoder *g_dec;
static struct voice_call_stats_s g_st;
static char     g_room[32];

static volatile int  g_mode = VC_MODE_LISTEN;
static volatile bool g_capture_active;      /* 采集线程正占用 I2S RX */
static volatile bool g_need_flush;          /* 进采集前需要 flush TX */
static volatile uint32_t g_last_remote_ms;  /* 最近一次"远端有话音"时刻 */
static volatile uint32_t g_mode_switches;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t vc_now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static uint32_t vc_ms32(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  return (uint32_t)((uint64_t)ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static int vc_ms32_diff(uint32_t newer, uint32_t older)
{
  uint32_t d = (newer - older) & 0xFFFFFFFFu;

  return (d < 0x80000000u) ? (int)d : -(int)(0xFFFFFFFFu - d);
}

/* 帧 RMS（16k mono PCM16）——整数实现（板端无 libm lrintf 之外依赖） */

static int vc_rms(const int16_t *pcm, int n)
{
  int64_t acc = 0;
  int r = 0;
  int i;

  if (n <= 0)
    {
      return 0;
    }

  for (i = 0; i < n; i++)
    {
      acc += (int32_t)pcm[i] * pcm[i];
    }

  acc /= n;

  while ((int64_t)r * r < acc)
    {
      r++;
    }

  return r;
}

static const char *vc_mode_name(int m)
{
  switch (m)
    {
      case VC_MODE_LISTEN:
        return "LISTEN(放远端)";

      case VC_MODE_PROBE:
        return "PROBE(试听本地)";

      default:
        return "TALK(本地说话)";
    }
}

static void vc_set_mode(int m)
{
  if (m != g_mode)
    {
      printf("[CALL] 模式切换 %s → %s\n", vc_mode_name(g_mode),
             vc_mode_name(m));
      g_mode = m;
      g_mode_switches++;
    }
}

static int vc_send(uint8_t type, uint32_t seq, uint16_t frames,
                   const void *payload, size_t plen)
{
  uint8_t buf[VC_MAX_PKT];
  struct vc_hdr_s *h = (struct vc_hdr_s *)buf;

  if (plen + VC_HDR_LEN > sizeof(buf))
    {
      return -EMSGSIZE;
    }

  h->magic = VC_MAGIC;
  h->type = type;
  h->sid = 0;
  h->seq = seq;
  h->ts_ms = vc_ms32();
  h->frames = frames;
  if (plen > 0)
    {
      memcpy(buf + VC_HDR_LEN, payload, plen);
    }

  return sendto(g_sock, buf, VC_HDR_LEN + plen, 0,
                (struct sockaddr *)&g_srv, sizeof(g_srv));
}

/* 16k mono → 24k stereo（3:2 线性插值 + L/R 复制），与 ai_voice 播放同口径 */

static int vc_play_pcm16k(const int16_t *pcm, int samples)
{
  static int16_t out[VC_FRAME * 3 / 2 * 2];
  int n_out = 0;
  int j;

  for (j = 0; j < samples * 3 / 2; j++)
    {
      uint32_t pos = (uint32_t)j * 2;
      uint32_t i = pos / 3;
      uint32_t frac = pos % 3;
      int16_t a = pcm[i];
      int16_t b = ((int)(i + 1) < samples) ? pcm[i + 1] : a;
      int16_t s = (frac == 0) ? a
                : (int16_t)(((int32_t)a * (3 - (int32_t)frac) +
                             (int32_t)b * (int32_t)frac) / 3);

      out[n_out++] = s;   /* L */
      out[n_out++] = s;   /* R */
    }

  return hal_i2s_write_async(out, (uint32_t)n_out * 2);
}

/****************************************************************************
 * TX 线程：采集 + 上行（仅在 PROBE/TALK 状态碰 I2S RX）
 ****************************************************************************/

static void *vc_tx_thread(void *arg)
{
  static int16_t mic24[VC_MIC24_FRAME];
  static int16_t pcm16[VC_FRAME];
  uint32_t seq = 0;
  int talk_frames = 0;
  int silence_ms = 0;

  (void)arg;

  while (g_run)
    {
      int m = g_mode;
      int n;
      int n16;
      int rms;

      if (m == VC_MODE_LISTEN)
        {
          /* 放音期间绝不采集（I2S 硬件约束）；等状态机切到 PROBE */

          usleep(5000);
          continue;
        }

      if (g_need_flush)
        {
          /* 反向切换前必须等 TX 排空，否则驱动报 -EIO */

          hal_i2s_write_flush();
          g_need_flush = false;
        }

      g_capture_active = true;
      n = hal_i2s_read_slot(mic24, sizeof(mic24), 0);   /* 20ms，阻塞 */
      g_capture_active = false;

      if (n <= 0)
        {
          usleep(2000);
          continue;
        }

      n16 = (int)ai_voice_decimate(pcm16, mic24, (uint32_t)(n / 2));
      if (n16 <= 0)
        {
          continue;
        }

      rms = vc_rms(pcm16, n16);
      g_st.local_rms = rms;

      if (m == VC_MODE_TALK)
        {
          if (vc_send(VC_T_AUDIO, seq++, 1, pcm16, (size_t)n16 * 2) > 0)
            {
              g_st.tx_packets++;
              g_st.tx_frames++;
            }

          /* 本地静音够久 → 让出，回 LISTEN 听远端 */

          if (rms < VC_ENERGY_TH)
            {
              silence_ms += 20;
              if (silence_ms >= VC_LOCAL_SIL_MS)
                {
                  silence_ms = 0;
                  vc_set_mode(VC_MODE_LISTEN);
                }
            }
          else
            {
              silence_ms = 0;
            }
        }
      else /* VC_MODE_PROBE：只听本地，不上行 */
        {
          if (rms >= VC_ENERGY_TH)
            {
              talk_frames++;
              if (talk_frames >= VC_TALK_FRAMES)
                {
                  talk_frames = 0;
                  silence_ms = 0;
                  vc_set_mode(VC_MODE_TALK);
                }
            }
          else
            {
              talk_frames = 0;
            }
        }
    }

  return NULL;
}

/****************************************************************************
 * RX 线程：收 index → 解码；LISTEN 时播放，同时做远端 VAD 与状态仲裁
 ****************************************************************************/

static void *vc_rx_thread(void *arg)
{
  static uint8_t buf[VC_MAX_PKT];
  static int16_t pcm[VC_FRAME * 4];
  uint32_t last_seq = 0;
  bool have_seq = false;

  (void)arg;

  while (g_run)
    {
      ssize_t n;
      struct vc_hdr_s *h;
      uint8_t *payload;
      int plen;
      int off = 0;
      int latency;

      n = recv(g_sock, buf, sizeof(buf), 0);
      if (n < VC_HDR_LEN)
        {
          if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK ||
                        errno == EINTR))
            {
              /* 收包超时也要做"远端静音 → 允许本地试听"的判定 */

              if (g_mode == VC_MODE_LISTEN &&
                  (vc_now_ms() - g_last_remote_ms) > VC_REMOTE_SIL_MS)
                {
                  g_need_flush = true;
                  vc_set_mode(VC_MODE_PROBE);
                }

              continue;
            }

          if (n <= 0)
            {
              usleep(2000);
              continue;
            }

          continue;
        }

      h = (struct vc_hdr_s *)buf;
      if (h->magic != VC_MAGIC || h->type != VC_T_AUDIO)
        {
          continue;
        }

      payload = buf + VC_HDR_LEN;
      plen = (int)n - VC_HDR_LEN;
      g_st.rx_packets++;
      g_st.rx_bytes += (uint32_t)plen;

      latency = vc_ms32_diff(vc_ms32(), h->ts_ms);
      if (latency >= 0 && latency < 5000)
        {
          g_st.last_latency_ms = latency;
        }

      if (have_seq)
        {
          uint32_t gap = (h->seq - last_seq) & 0xFFFFFFFFu;

          if (gap > 1 && gap < 100)
            {
              g_st.rx_lost += gap - 1;
            }
        }

      last_seq = h->seq;
      have_seq = true;

      /* 切包（2B 长度前缀）→ 解码；无论放不放音都算能量做远端 VAD */

      while (off + 2 <= plen)
        {
          int ln = payload[off] | (payload[off + 1] << 8);
          int m;

          off += 2;
          if (ln <= 0 || off + ln > plen)
            {
              break;
            }

          m = opus_decode(g_dec, payload + off, ln, pcm, VC_FRAME * 4, 0);
          off += ln;

          if (m > 0)
            {
              int rms = vc_rms(pcm, m);

              g_st.rx_frames++;
              g_st.remote_rms = rms;

              if (rms >= VC_ENERGY_TH)
                {
                  g_last_remote_ms = vc_now_ms();

                  /* 远端在说话：本地无论处于哪一态都让出（听优先） */

                  if (g_mode != VC_MODE_LISTEN)
                    {
                      vc_set_mode(VC_MODE_LISTEN);
                    }
                }

              if (g_mode == VC_MODE_LISTEN)
                {
                  /* 等采集线程退出（≤60ms）再放音，避免 TX/RX 冲突 */

                  uint32_t t0 = vc_now_ms();

                  while (g_capture_active &&
                         (vc_now_ms() - t0) < VC_SWITCH_WAIT_MS)
                    {
                      usleep(1000);
                    }

                  vc_play_pcm16k(pcm, m);
                }
            }
          else if (m < 0)
            {
              printf("[CALL] opus_decode 失败: %d\n", m);
            }
        }

      /* 远端静音够久且当前在 LISTEN → 允许本地试听 */

      if (g_mode == VC_MODE_LISTEN &&
          (vc_now_ms() - g_last_remote_ms) > VC_REMOTE_SIL_MS)
        {
          g_need_flush = true;
          vc_set_mode(VC_MODE_PROBE);
        }
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int voice_call_start(const char *server_host, uint16_t port, const char *room)
{
  struct sockaddr_in local;
  struct timeval tv;
  pthread_attr_t attr;
  int err = OPUS_OK;
  int ret;

  if (g_run)
    {
      printf("[CALL] 已在通话中（先 plant call stop）\n");
      return -EBUSY;
    }

  if (server_host == NULL || room == NULL)
    {
      return -EINVAL;
    }

  memset(&g_st, 0, sizeof(g_st));
  memset(&g_srv, 0, sizeof(g_srv));
  g_srv.sin_family = AF_INET;
  g_srv.sin_port = htons(port);
  g_srv.sin_addr.s_addr = inet_addr(server_host);
  if (g_srv.sin_addr.s_addr == INADDR_NONE)
    {
      printf("[CALL] 服务器地址非法: %s\n", server_host);
      return -EINVAL;
    }

  g_sock = socket(AF_INET, SOCK_DGRAM, 0);
  if (g_sock < 0)
    {
      printf("[CALL] socket 失败: %d\n", errno);
      return -errno;
    }

  memset(&local, 0, sizeof(local));
  local.sin_family = AF_INET;
  local.sin_addr.s_addr = htonl(INADDR_ANY);
  local.sin_port = 0;
  if (bind(g_sock, (struct sockaddr *)&local, sizeof(local)) < 0)
    {
      printf("[CALL] bind 失败: %d\n", errno);
      close(g_sock);
      g_sock = -1;
      return -errno;
    }

  tv.tv_sec = 0;
  tv.tv_usec = 100 * 1000;      /* 100ms：便于周期性做远端静音判定 */
  setsockopt(g_sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  g_dec = opus_decoder_create(VC_RATE, 1, &err);
  if (g_dec == NULL || err != OPUS_OK)
    {
      printf("[CALL] opus_decoder_create 失败: %d\n", err);
      close(g_sock);
      g_sock = -1;
      return -EIO;
    }

  g_st.decoder_state = opus_decoder_get_size(1);
  strncpy(g_room, room, sizeof(g_room) - 1);
  g_room[sizeof(g_room) - 1] = '\0';

  g_mode = VC_MODE_LISTEN;
  g_capture_active = false;
  g_need_flush = false;
  g_last_remote_ms = vc_now_ms();
  g_run = true;

  ret = vc_send(VC_T_HELLO, 0, 0, g_room, strlen(g_room));
  if (ret < 0)
    {
      printf("[CALL] HELLO 发送失败: %d\n", errno);
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  pthread_create(&g_tx_tid, &attr, vc_tx_thread, NULL);
  pthread_create(&g_rx_tid, &attr, vc_rx_thread, NULL);
  pthread_attr_destroy(&attr);

  printf("[CALL] 通话已启动（半双工自动切换）: %s:%u room=%s 解码器=%d B\n",
         server_host, (unsigned)port, g_room, g_st.decoder_state);
  printf("[CALL] 上行 16k PCM → 服务器 Opus 编码 → 对端；下行 index → 板端解码\n");
  printf("[CALL] 门限 RMS=%d，远端静音 %dms 让本地试听，本地静音 %dms 让回远端\n",
         VC_ENERGY_TH, VC_REMOTE_SIL_MS, VC_LOCAL_SIL_MS);
  return 0;
}

void voice_call_stop(void)
{
  if (!g_run)
    {
      return;
    }

  g_run = false;

  vc_send(VC_T_BYE, 0, 0, NULL, 0);

  pthread_join(g_tx_tid, NULL);
  pthread_join(g_rx_tid, NULL);

  hal_i2s_write_flush();

  if (g_dec != NULL)
    {
      opus_decoder_destroy(g_dec);
      g_dec = NULL;
    }

  if (g_sock >= 0)
    {
      close(g_sock);
      g_sock = -1;
    }

  printf("[CALL] 通话已结束（tx=%u 包 / rx=%u 包 / 丢 %u / 切换 %u 次）\n",
         g_st.tx_packets, g_st.rx_packets, g_st.rx_lost, g_mode_switches);
}

bool voice_call_running(void)
{
  return g_run;
}

void voice_call_get_stats(struct voice_call_stats_s *out)
{
  if (out != NULL)
    {
      *out = g_st;
      out->mode = g_mode;
      out->switches = g_mode_switches;
    }
}

void voice_call_print_stats(void)
{
  struct voice_call_stats_s s;
  double secs;

  voice_call_get_stats(&s);
  secs = (double)(s.tx_frames * 20) / 1000.0;

  printf("[CALL] ==== 通话统计（半双工）====\n");
  printf("[CALL] 当前模式: %s | 切换 %u 次\n",
         vc_mode_name(s.mode), s.switches);
  printf("[CALL] 上行: %u 包 / %u 帧 (%.1fs) = %.1f kbps PCM\n",
         s.tx_packets, s.tx_frames, secs,
         secs > 0 ? (double)s.tx_frames * VC_FRAME * 2 * 8 / secs / 1000.0 : 0.0);
  printf("[CALL] 下行: %u 包 / %u 帧 / 丢 %u / index %u B = %.1f kbps\n",
         s.rx_packets, s.rx_frames, s.rx_lost, s.rx_bytes,
         secs > 0 ? (double)s.rx_bytes * 8 / secs / 1000.0 : 0.0);
  printf("[CALL] 能量: 本地 RMS %d / 远端 RMS %d（门限 %d）\n",
         s.local_rms, s.remote_rms, VC_ENERGY_TH);
  printf("[CALL] 单向延迟(最近): %d ms | 解码器状态 %d B\n",
         s.last_latency_ms, s.decoder_state);
  printf("[CALL] ==========================\n");
}
