int sd_card_init(void)
{
  printf("[SD] init: probing %s...\n", SD_DEVICE);

  /* 2026-09-03（用户定案）：自动挂载最多 SD_MOUNT_RETRIES 次（sd_card_mount
   * 内部 5×300ms），失败即停——不再起后台预热线程 30s 循环（坏卡/无卡时
   * 反复访问 SD_CMD(IO0) 并刷屏）。之后可手动 `plant sd mount`。 */

  if (sd_card_mount() == 0)
    {
      return 0;
    }

  printf("[SD] 自动挂载失败（已试 %d 次）。可用 'plant sd mount' 手动重试；"
         "卡需开机前插好（无卡检测脚）。\n", SD_MOUNT_RETRIES);
  return -1;
}

